def ai_login(client, model="Sonnet"):
    r = client.post("/lobby/join", json={"name": "KI", "model": model})
    assert r.status_code == 200, r.text
    return {"Authorization": f"Bearer {r.json()['token']}"}


def fake_robots(app):
    app.robots = [SimpleNamespace(id=i, present=True, pos=np.array([100.0 * i, 200.0]), outline=None,
                                  vel=np.array([12.34, 0.0]), radius=40.0) for i in (1, 2)]


def test_ai_client_says_and_reports_only_for_itself(client):
    app = client.app_state
    fake_robots(app)
    human = login(client, "Kiste")
    ai = ai_login(client)
    assert client.post("/api/say", json={"text": "Hallo"}, headers=human).status_code == 403
    assert client.post("/api/ai_status", json={"status": {}}, headers=human).status_code == 403
    r = client.post("/api/say", json={"player": 1, "text": "Gleich knallt's!"}, headers=ai)
    assert r.status_code == 200
    assert app.says[2][0] == "Gleich knallt's!" and 1 not in app.says
    status = {"status": "Kämpft", "model": "Sonnet", "calls": 3, "comment": "x" * 300, "dry": True,
              "secret": "weg", "error": None}
    assert client.post("/api/ai_status", json={"status": status}, headers=ai).status_code == 200
    assert app.ai_status[2] == {"status": "Kämpft", "model": "Sonnet", "calls": 3, "comment": "x" * 120}
    state = app.state(0)
    robots = {r["id"]: r for r in state["robots"]}
    assert robots[1]["ai"] is False and robots[2]["ai"] is True
    assert [p.get("status", {}).get("calls") for p in state["lobby"]["players"]] == [None, 3]
    assert (robots[2]["vel"], robots[2]["radius"]) == ([12.3, 0.0], 40.0)
    mod = login(client, "mod", "admin")
    assert client.post("/api/kick", json={"slot": 2}, headers=mod).status_code == 200
    assert client.post("/api/say", json={"text": "Noch da?"}, headers=ai).status_code == 403


def test_say_is_trimmed_and_expires(client):
    app = client.app_state
    fake_robots(app)
    app.cfg.say_s = 0.2
    app.act("say", {"player": 2, "text": "  Gleich  knallt's! " + "x" * 200})
    text, end = app.says[2]
    assert text.startswith("Gleich knallt's! x") and len(text) == 80
    robot = next(r for r in app.state(end - 0.01)["robots"] if r["id"] == 2)
    assert robot["say"] == text
    assert next(r for r in app.state(end + 0.01)["robots"] if r["id"] == 2)["say"] is None
    app.act("say", {"player": 2, "text": "   "})
    assert 2 not in app.says
